import itertools, pytest
import _pytest.mark.structures as ms
print("pytest file:", pytest.__file__)

class BaseMeta(type):
    @property
    def pytestmark(self):
        return (getattr(self, "_pytestmark", []) +
                list(itertools.chain.from_iterable(getattr(x, "_pytestmark", []) for x in self.__mro__)))
    @pytestmark.setter
    def pytestmark(self, value):
        self._pytestmark = value

class Base(object, metaclass=BaseMeta):
    pass

@pytest.mark.foo
class Foo(Base): pass

@pytest.mark.bar
class Bar(Base): pass

class TestDings(Foo, Bar):
    def test_dings(self): pass

@pytest.mark.foo
class FooPlain: pass
@pytest.mark.bar
class BarPlain: pass
class TestDingsPlain(FooPlain, BarPlain):
    def test_dings_plain(self): pass

for cls in (TestDings, TestDingsPlain):
    marks = [m.name for m in ms.get_unpacked_marks(cls)]
    print(cls.__name__, "get_unpacked_marks:", marks)
    print(cls.__name__, "getattr pytestmark:", [m.name for m in getattr(cls, "pytestmark", [])])
